begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select no_plan();
insert into auth.users(id,email) values ('11111111-1111-1111-1111-111111111119','revisit-owner@example.test'),('22222222-2222-2222-2222-222222222229','revisit-other@example.test');
insert into public.captures(id,user_id,capture_channel,captured_at,raw_text)
select ('aaaaaaaa-aaaa-aaaa-aaaa-'||lpad(i::text,12,'0'))::uuid,'11111111-1111-1111-1111-111111111119','email','2026-01-01'::timestamptz + (i/2)*interval '1 day', case when i=3 then 'https://example.com/article' end from generate_series(1,7) i;
insert into public.captures(id,user_id,capture_channel,captured_at) values('bbbbbbbb-bbbb-bbbb-bbbb-bbbbbbbbbbb9','22222222-2222-2222-2222-222222222229','email',now());
insert into public.capture_analyses(id,capture_id,analysis_type,status,input_snapshot,result,model_id,prompt_version,pipeline_version)
select ('cccccccc-cccc-cccc-cccc-'||lpad(i::text,12,'0'))::uuid,('aaaaaaaa-aaaa-aaaa-aaaa-'||lpad(i::text,12,'0'))::uuid,'intent','succeeded','{}','{"interest":"frozen"}','model','v1','v1' from generate_series(4,7) i;
create temp table frozen as select id,result from public.capture_analyses;
set local role authenticated;
select set_config('request.jwt.claim.sub','11111111-1111-1111-1111-111111111119',true);
select results_eq('select revisit_batch()', $$values ('aaaaaaaa-aaaa-aaaa-aaaa-000000000001'::uuid),('aaaaaaaa-aaaa-aaaa-aaaa-000000000002'::uuid),('aaaaaaaa-aaaa-aaaa-aaaa-000000000003'::uuid)$$,'AC1 stable oldest-first batch includes unanalysed saves and caps at three');
select results_eq('select revisit_batch()', $$values ('aaaaaaaa-aaaa-aaaa-aaaa-000000000001'::uuid),('aaaaaaaa-aaaa-aaaa-aaaa-000000000002'::uuid),('aaaaaaaa-aaaa-aaaa-aaaa-000000000003'::uuid)$$,'AC1 same state yields same batch');
select is((select count(*)::int from capture_revisit_state where first_exposed_at is not null),3,'AC2 exposure durable for every released batch card');
create temp table exposure as select first_exposed_at from capture_revisit_state where capture_id='aaaaaaaa-aaaa-aaaa-aaaa-000000000001';
select ok(revisit_expose('aaaaaaaa-aaaa-aaaa-aaaa-000000000001'),'AC2 single-card exposure succeeds');
select is((select first_exposed_at from capture_revisit_state where capture_id='aaaaaaaa-aaaa-aaaa-aaaa-000000000001'),(select first_exposed_at from exposure),'AC2 original exposure timestamp preserved');
select ok(not revisit_expose('bbbbbbbb-bbbb-bbbb-bbbb-bbbbbbbbbbb9'),'AC6 foreign exposure refused');
select ok(not revisit_expose('dddddddd-dddd-dddd-dddd-dddddddddddd'),'AC6 unknown exposure refused');
select is(revisit_action('aaaaaaaa-aaaa-aaaa-aaaa-000000000001','dddddddd-dddd-dddd-dddd-000000000001','defer')->>'repeated','false','AC3 deferral applies once');
create temp table deferred as select deferred_until from capture_revisit_state where capture_id='aaaaaaaa-aaaa-aaaa-aaaa-000000000001';
select is(revisit_action('aaaaaaaa-aaaa-aaaa-aaaa-000000000001','dddddddd-dddd-dddd-dddd-000000000001','defer')->>'repeated','true','AC3 retry is idempotent');
select is((select deferred_until from capture_revisit_state where capture_id='aaaaaaaa-aaaa-aaaa-aaaa-000000000001'),(select deferred_until from deferred),'AC3 retry cannot extend deferral');
select is((select s.deferred_until-e.occurred_at from capture_revisit_state s join capture_revisit_events e using(capture_id) where e.request_id='dddddddd-dddd-dddd-dddd-000000000001'),interval '7 days','AC1 deferral is seven days from server time');
select is(revisit_action('aaaaaaaa-aaaa-aaaa-aaaa-000000000002','dddddddd-dddd-dddd-dddd-000000000002','consume')->>'repeated','false','AC3 explicit consumption applies');
select is(revisit_action('aaaaaaaa-aaaa-aaaa-aaaa-000000000002','dddddddd-dddd-dddd-dddd-000000000002','consume')->>'repeated','true','AC3 consumption retry is idempotent');
select results_eq('select revisit_batch()', $$values ('aaaaaaaa-aaaa-aaaa-aaaa-000000000003'::uuid),('aaaaaaaa-aaaa-aaaa-aaaa-000000000004'::uuid),('aaaaaaaa-aaaa-aaaa-aaaa-000000000005'::uuid)$$,'AC1 deferred and consumed absent after another request');
select is(research_record_recall('aaaaaaaa-aaaa-aaaa-aaaa-000000000004','remembered','fresh')->>'status','exposed','AC4 stale recall rejected after exposure');
select is((select count(*)::int from capture_evaluations),0,'AC4 rejected recall writes no rows');
select is((select count(*)::int from research_pending_evaluations),2,'AC4 exposed fresh captures excluded from selection');
select is(research_record_recall('aaaaaaaa-aaaa-aaaa-aaaa-000000000006','remembered','original')->>'runs','1','AC4 recall stored before exposure accepted');
create temp table saved_evaluations as select * from capture_evaluations where capture_id='aaaaaaaa-aaaa-aaaa-aaaa-000000000006';
select ok(revisit_expose('aaaaaaaa-aaaa-aaaa-aaaa-000000000006'),'AC4 later exposure allowed');
select is(research_record_recall('aaaaaaaa-aaaa-aaaa-aaaa-000000000006','partial','changed')->>'repeated','true','AC4 existing recall resumes after exposure');
select is((select remembered_interest from capture_evaluations where capture_id='aaaaaaaa-aaaa-aaaa-aaaa-000000000006'),'original','AC4 persisted recall unchanged');
select results_eq($$select row_to_json(e)::text from capture_evaluations e where capture_id='aaaaaaaa-aaaa-aaaa-aaaa-000000000006'$$,$$select row_to_json(e)::text from saved_evaluations e$$,'AC4 every previously persisted evaluation column remains identical');
select ok(exists(select 1 from research_pending_evaluations where capture_id='aaaaaaaa-aaaa-aaaa-aaaa-000000000006' and recall_stored),'AC4 recalled unrated save remains selectable');
select throws_ok($$select revisit_action('aaaaaaaa-aaaa-aaaa-aaaa-000000000003','dddddddd-dddd-dddd-dddd-000000000004','open','https://unrelated.example/other')$$,'22023','Destination unavailable','AC3 direct caller cannot invent an available source');
select is(revisit_action('aaaaaaaa-aaaa-aaaa-aaaa-000000000003','dddddddd-dddd-dddd-dddd-000000000004','open','https://example.com/article')->>'repeated','false','AC3 Open records attempt');
select is(revisit_action('aaaaaaaa-aaaa-aaaa-aaaa-000000000003','dddddddd-dddd-dddd-dddd-000000000004','open','https://example.com/article')->>'repeated','true','AC3 Open retry applies once');
select is((select count(*)::int from capture_revisit_events where action='open'),1,'AC3 exactly one Open attempt event');
select ok((select consumed_at is null from capture_revisit_state where capture_id='aaaaaaaa-aaaa-aaaa-aaaa-000000000003'),'AC3 Open never claims consumption');
select throws_ok($$select revisit_action('aaaaaaaa-aaaa-aaaa-aaaa-000000000003','dddddddd-dddd-dddd-dddd-000000000003','invalid')$$,'22023','Invalid action','AC6 invalid action fails closed');
select throws_ok($$select revisit_action('bbbbbbbb-bbbb-bbbb-bbbb-bbbbbbbbbbb9','dddddddd-dddd-dddd-dddd-000000000003','defer')$$,'42501','Unavailable','AC6 foreign action refused');
select throws_ok($$select revisit_action('aaaaaaaa-aaaa-aaaa-aaaa-000000000003','dddddddd-dddd-dddd-dddd-000000000003','open')$$,'22023','Destination unavailable','AC7 no fabricated Open without destination');
select throws_ok($$select revisit_action('aaaaaaaa-aaaa-aaaa-aaaa-000000000001','dddddddd-dddd-dddd-dddd-000000000001','consume')$$,'22023','Request conflict','AC3 request ID cannot be reused for another action');
select throws_ok($$insert into capture_revisit_state(capture_id,user_id) values('aaaaaaaa-aaaa-aaaa-aaaa-000000000007','11111111-1111-1111-1111-111111111119')$$,'42501',null,'AC6 direct metadata writes denied');
select set_config('request.jwt.claim.sub','22222222-2222-2222-2222-222222222229',true);
select is((select count(*)::int from capture_revisit_state),0,'AC6 other owner reads no state');
select is((select count(*)::int from capture_revisit_events),0,'AC6 other owner reads no events');
select is((select count(*)::int from captures),1,'AC6 other owner only reads owned captures');
reset role;
update capture_revisit_state set deferred_until=clock_timestamp()-interval '1 second' where capture_id='aaaaaaaa-aaaa-aaaa-aaaa-000000000001';
set local role authenticated;
select set_config('request.jwt.claim.sub','11111111-1111-1111-1111-111111111119',true);
select results_eq('select revisit_batch()', $$values ('aaaaaaaa-aaaa-aaaa-aaaa-000000000001'::uuid),('aaaaaaaa-aaaa-aaaa-aaaa-000000000003'::uuid),('aaaaaaaa-aaaa-aaaa-aaaa-000000000004'::uuid)$$,'AC1 elapsed deferral returns while consumed stays absent');
reset role;
select results_eq('select id,result from public.capture_analyses order by id','select id,result from frozen order by id','AC4 frozen analyses remain identical');
select throws_ok($$insert into capture_revisit_state(capture_id,user_id) values('bbbbbbbb-bbbb-bbbb-bbbb-bbbbbbbbbbb9','11111111-1111-1111-1111-111111111119')$$,'23503',null,'AC6 owner/capture FK rejects privileged foreign state');
insert into storage.objects(bucket_id,name) values('capture-assets','captures/11111111-1111-1111-1111-111111111119/aaaaaaaa-aaaa-aaaa-aaaa-000000000007/private.png');
set local role authenticated;
select set_config('request.jwt.claim.sub','11111111-1111-1111-1111-111111111119',true);
select is((select count(*)::int from storage.objects where name like '%/private.png'),0,'AC2 direct asset access cannot bypass exposure');
select ok(revisit_expose('aaaaaaaa-aaaa-aaaa-aaaa-000000000007'),'AC2 asset exposure commits before owned object access');
select is((select count(*)::int from storage.objects where name like '%/private.png'),1,'AC2 exposed owner can access exact private object');
select set_config('request.jwt.claim.sub','22222222-2222-2222-2222-222222222229',true);
select is((select count(*)::int from storage.objects where name like '%/private.png'),0,'AC6 stranger cannot access exposed private object');
reset role;
set local role anon;
select throws_ok('select * from public.capture_revisit_state','42501',null,'AC6 anonymous reads denied');
select throws_ok($$select public.revisit_expose('aaaaaaaa-aaaa-aaaa-aaaa-000000000001')$$,'42501',null,'AC6 anonymous exposure denied');
reset role;
select * from finish();
rollback;
